import Foundation

/// Calendar exceptions avoid assuming every local day has exactly 24 hours.
/// The clock exists only while powered; its plan is regenerated by the phone.
public struct ActivityClockPlan: Equatable {
    public let epoch: UInt32
    public let day: UInt32
    public let nextEpoch: UInt32
    public let validUntil: UInt32
    public let exceptions: [(UInt32,UInt32)]
    public static func == (a: Self,b: Self) -> Bool {
        a.epoch==b.epoch && a.day==b.day && a.nextEpoch==b.nextEpoch && a.validUntil==b.validUntil &&
        a.exceptions.elementsEqual(b.exceptions,by:{$0.0==$1.0 && $0.1==$1.1})
    }
    public static func make(now:Date=Date(),timeZone:String) throws -> Self {
        guard now.timeIntervalSince1970.isFinite,now.timeIntervalSince1970>0 else { throw PhysicalError.message("请检查手机日期") }
        guard let tz=TimeZone(identifier:timeZone) else { throw PhysicalError.message("校时时区无效") }
        var c=Calendar(identifier:.gregorian);c.timeZone=tz
        var parts=c.dateComponents([.year,.month,.day],from:now);parts.hour=8
        guard let today=c.date(from:parts),let start=now<today ? c.date(byAdding:.day,value:-1,to:today) : today,
              let next=c.date(byAdding:.day,value:1,to:start) else { throw CompanionError.invalidState }
        func seconds(_ date:Date) throws -> UInt32 {
            let n=floor(date.timeIntervalSince1970)
            guard n>0,n<Double(UInt32.max) else { throw PhysicalError.message("请检查手机日期") }
            return UInt32(n)
        }
        func ordinal(_ date:Date) throws -> UInt32 {
            var utc=Calendar(identifier:.gregorian);utc.timeZone=TimeZone(secondsFromGMT:0)!
            let parts=c.dateComponents([.year,.month,.day],from:date)
            guard let midnight=utc.date(from:parts) else { throw CompanionError.invalidState }
            let n=floor(midnight.timeIntervalSince1970/86400)+719163
            guard n>0,n<=3652059 else { throw CompanionError.invalidState }
            return UInt32(n)
        }
        var cursor=start,exceptions:[(UInt32,UInt32)]=[]
        for _ in 0..<3660 {
            guard let end=c.date(byAdding:.day,value:1,to:cursor) else { throw CompanionError.invalidState }
            let length=UInt32(end.timeIntervalSince(cursor))
            guard (72000...100800).contains(length),length%60==0 else { throw PhysicalError.message("当前时区日历需要重新确认") }
            if length != 86400 { exceptions.append((try ordinal(cursor),length)) }
            cursor=end
        }
        guard exceptions.count<=24 else { throw PhysicalError.message("当前时区变化过多，暂不支持离线校时") }
        return try Self(epoch:seconds(now),day:ordinal(start),nextEpoch:seconds(next),validUntil:seconds(cursor),exceptions:exceptions)
    }
    public func payload(receipt:ActivityReward) throws -> String {
        try receipt.validate()
        guard receipt.profileID==3,receipt.offlineClockSupported==true,day>=receipt.day else {
            throw PhysicalError.message("请检查手机时间，不能回退已确认的活动周期")
        }
        var words:[UInt32]=[epoch,day,nextEpoch,validUntil,receipt.day,receipt.earnedToday,receipt.profileID,0,UInt32(exceptions.count)]
        for (day,duration) in exceptions { words.append(day);words.append(duration) }
        return words.map { String($0) }.joined(separator:",")
    }
}
